(function(){'use strict';const requests={"island-overture": "I am interested in Island Overture (10 days). Suggested route: Colombo → Sigiriya → Kandy → Ella → Yala → Galle → Colombo. Please help me personalise this itinerary around my dates and interests.", "kingdoms-and-quiet-temples": "I am interested in Kingdoms & Quiet Temples (7 days). Suggested route: Negombo → Anuradhapura → Sigiriya → Polonnaruwa → Sigiriya → Dambulla → Kandy → Colombo. Please help me personalise this itinerary around my dates and interests.", "tea-trails-and-waterfalls": "I am interested in Tea Trails & Waterfalls (7 days). Suggested route: Colombo → Kandy → Nuwara Eliya → Ella → Haputale → Belihuloya → Colombo. Please help me personalise this itinerary around my dates and interests.", "wild-hearts-of-ceylon": "I am interested in Wild Hearts of Ceylon (8 days). Suggested route: Negombo → Sinharaja → Udawalawe → Tissamaharama → Yala → Tangalle → Colombo. Please help me personalise this itinerary around my dates and interests.", "saltwater-and-slow-days": "I am interested in Saltwater & Slow Days (7 days). Suggested route: Colombo → Galle → Unawatuna → Weligama → Mirissa → Tangalle → Colombo. Please help me personalise this itinerary around my dates and interests."};const slug=new URLSearchParams(location.search).get('tour');if(!Object.prototype.hasOwnProperty.call(requests,slug))return;const field=document.querySelector('#inquiry textarea[name=message]');if(!field)return;const request=requests[slug];if(!field.value.includes(request))field.value+=(field.value?'\n\n':'')+request;document.querySelector('#inquiry select[name=interest]').selectedIndex=0;document.querySelector('#form-status').textContent='Your chosen itinerary is added to the draft below. Complete your contact details to save your enquiry. Nothing has been sent.';function show(){document.querySelector('#inquiry').scrollIntoView({behavior:'instant',block:'start'});field.focus({preventScroll:true});}if(document.readyState==='complete')show();else window.addEventListener('load',show,{once:true});})();
